CREATE TABLE users (uid CHAR(36) PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3), updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3));
CREATE TABLE businesses (uid CHAR(36) PRIMARY KEY, name VARCHAR(200) NOT NULL, tax_id VARCHAR(32) NOT NULL, tax_profile JSON NOT NULL, created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3), updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3));
CREATE TABLE business_users (uid CHAR(36) PRIMARY KEY, business_uid CHAR(36) NOT NULL, user_uid CHAR(36) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'owner', created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3), updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), UNIQUE(business_uid,user_uid), FOREIGN KEY(business_uid) REFERENCES businesses(uid) ON DELETE CASCADE, FOREIGN KEY(user_uid) REFERENCES users(uid) ON DELETE CASCADE);
CREATE TABLE user_sessions (uid CHAR(36) PRIMARY KEY, user_uid CHAR(36) NOT NULL, business_uid CHAR(36) NOT NULL, expires_at DATETIME(3) NOT NULL, revoked BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3), updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), INDEX(user_uid), FOREIGN KEY(user_uid) REFERENCES users(uid) ON DELETE CASCADE, FOREIGN KEY(business_uid) REFERENCES businesses(uid) ON DELETE CASCADE);
CREATE TABLE refresh_tokens (uid CHAR(36) PRIMARY KEY, session_uid CHAR(36) NOT NULL UNIQUE, business_uid CHAR(36) NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3), updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), FOREIGN KEY(session_uid) REFERENCES user_sessions(uid) ON DELETE CASCADE, FOREIGN KEY(business_uid) REFERENCES businesses(uid) ON DELETE CASCADE);
CREATE TABLE audit_logs (uid CHAR(36) PRIMARY KEY, business_uid CHAR(36) NOT NULL, user_uid CHAR(36) NOT NULL, action VARCHAR(100) NOT NULL, created_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3), updated_at TIMESTAMP(3) DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), INDEX(business_uid,created_at), FOREIGN KEY(business_uid) REFERENCES businesses(uid) ON DELETE CASCADE);
